{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Pentosan polysulfate sodium, a highly sulfated polysaccharide with multiple sulfate esters and polar hydroxyls, has oral bioavailability of only 0.5-1% in healthy subjects, directly supporting very low F for the query's sulfated saccharide scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Dextran sulfate, another highly sulfated polysaccharide, is reported to have poor oral bioavailability in humans, supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Zanamivir, a polar sialic-acid derivative with carboxylate and multiple hydroxyls, has absolute oral bioavailability of only 2% (range 1-5%) in volunteers, supporting low F for the query's highly polar carbohydrate.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Acamprosate, a small molecule containing a sulfonate group, has absolute oral bioavailability of approximately 11% under fasting conditions, below the 20% threshold, supporting low F for the query's ionized sulfate/carboxylate.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Glucoraphanin, a glucosinolate with a sulfate group and sugar moiety, has mean oral bioavailability of only 5% in humans, supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Levovirin, a highly polar nucleoside with very low Caco-2 permeability, has ~10% oral bioavailability in humans, supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Direct oral administration of oseltamivir carboxylate, a polar ionizable carboxylate, gives <5% bioavailability in humans, consistent with low F; the high-F prodrug data are not applicable to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Ribavirin, a polar nucleoside, has approximately 52% oral bioavailability in humans, a high-F example; however, its very low transferability to the sulfated disaccharide query means it does not outweigh the direct low-F analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a highly polar, ionized sulfated disaccharide (N-acetylgalactosamine-4-sulfate linked to glucuronic acid). Directly transferable evidence from sulfated polysaccharides (pentosan polysulfate 0.5-1%, dextran sulfate poor) and polar saccharide/sulfonate drugs (zanamivir 2%, acamprosate 11%, glucoraphanin 5%, levovirin 10%) all show oral bioavailability well below 20%. The high-F ribavirin and oseltamivir prodrug data have very low transferability and do not apply. Therefore predict low.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability study for the exact disaccharide; extrapolation from closely related sulfated polysaccharides and polar saccharides.",
    "Potential active uptake or gut metabolism of the disaccharide is not experimentally characterized.",
    "The sulfate ester may be hydrolyzed in the GI tract, but no data are available to assess this."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

